1	package darksafe
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"sort"
10		"strings"
11	)
12	
13	// Reason constants for clusters that cannot enter a release plan.
14	const (
15		ReasonDisabled          = "集群已停用"
16		ReasonExcludeMatched    = "命中排除条件"
17		ReasonIncludeNotMatched = "未命中包含条件"
18	)
19	
20	// LabelCondition is a set of exact key-value matches; all must match.
21	type LabelCondition map[string]string
22	
23	// Cluster is a candidate target for a release.
24	type Cluster struct {
25		ID       string
26		Disabled bool
27		Tags     map[string]string
28	}
29	
30	// ReleasePlanInput describes an application release to plan offline.
31	type ReleasePlanInput struct {
32		App       string
33		Revision  string
34		Image     string
35		BatchSize int
36		Clusters  []Cluster
37		Include   []LabelCondition
38		Exclude   []LabelCondition
39		// SpreadBy, when non-empty, names a cluster tag whose value identifies a
40		// fault domain; each batch then contains at most one cluster per domain.
41		SpreadBy string
42	}
43	
44	// AppInfo identifies the application being released.
45	type AppInfo struct {
46		Name     string `json:"name"`
47		Revision string `json:"revision"`
48		Image    string `json:"image"`
49	}
50	
51	// Batch is a sequentially numbered group of cluster IDs.
52	type Batch struct {
53		Index    int      `json:"index"`
54		Clusters []string `json:"clusters"`
55	}
56	
57	// ExcludedCluster explains why a cluster is not in the plan.
58	type ExcludedCluster struct {
59		ID     string `json:"id"`
60		Reason string `json:"reason"`
61	}
62	
63	// ReleasePlan is the deterministic offline release plan.
64	type ReleasePlan struct {
65		App      AppInfo           `json:"app"`
66		Batches  []Batch           `json:"batches"`
67		Excluded []ExcludedCluster `json:"excluded"`
68	}
69	
70	// ParseReleaseInput reads a release plan document and validates its fields.
71	// Every string in the document — member names and values, in known fields
72	// and in unknown extra fields — must be legal text: invalid UTF-8 bytes and
73	// \uXXXX escapes naming an unpaired surrogate are rejected first, before any
74	// decoded string can be silently rewritten to "�" and compared. Every JSON
75	// object in the document — including unknown fields and their nested
76	// objects — must then have distinct member names; a name appearing twice
77	// (even with the same value, or via equivalent Unicode escapes) is rejected
78	// before any business validation runs.
79	func ParseReleaseInput(data []byte) (ReleasePlanInput, error) {
80		if err := checkStrictText(data); err != nil {
81			return ReleasePlanInput{}, err
82		}
83		if err := checkDuplicateMembers(data); err != nil {
84			return ReleasePlanInput{}, err
85		}
86		dec := json.NewDecoder(bytes.NewReader(data))
87		dec.UseNumber()
88		var doc map[string]any
89		if err := dec.Decode(&doc); err != nil {
90			return ReleasePlanInput{}, fmt.Errorf("JSON 格式错误: %w", err)
91		}
92		if dec.More() {
93			return ReleasePlanInput{}, errors.New("JSON 格式错误: 文档包含多余内容")
94		}
95		return buildReleaseInput(doc)
96	}
97	
98	// duplicateMemberError reports a JSON object whose member name appears more
99	// than once. Path is a JSONPath-style location that points at the object
100	// owning the duplicate (the duplicate member name itself is reported
101	// separately in field): "$" for the document root, "$.clusters[1]" for a
102	// cluster, "$.clusters[0].tags" for a tag object,
103	// "$.include[2]" / "$.exclude[1]" for a condition, and "$.foo.bar[0]" for
104	// objects nested inside unknown fields. A member name that is not a plain
105	// identifier is wrapped in brackets around a JSON string, so that characters
106	// in the name can never be read as hierarchy or an array index: a top-level
107	// member "meta.info" is at $["meta.info"] (distinct from the nested object
108	// $.meta.info), "zone[0]" stays one whole name at $["zone[0]"], and names
109	// that are empty or contain quotes, backslashes or control characters are
110	// rendered as decodable JSON strings such as $[""] or $["a\nb"].
111	type duplicateMemberError struct {
112		field string
113		path  string
114	}
115	
116	func (e *duplicateMemberError) Error() string {
117		return fmt.Sprintf("JSON 对象存在重复成员: 字段 %q 重复出现于 %s", e.field, e.path)
118	}
119	
120	// checkDuplicateMembers walks every JSON object in data and rejects objects
121	// with duplicate member names. Names are compared after JSON decoding, so
122	// "env" and "env" are the same name while "env" and "ENV", or
123	// " env" and "env", are different. The first duplicate encountered in file
124	// order is reported: the walk is depth-first in document order, so the
125	// second occurrence that appears earliest wins, regardless of value type.
126	//
127	// The check is a policy over the shared structural walk (jsonwalk.go): the
128	// walker recognizes the nesting, decodes the member names and tracks each
129	// object's location; this check only keeps the seen-name set of each object.
130	// A document the walk cannot fully vouch for — an unrecognized structure,
131	// trailing content, or a loosely scanned number only the decoder judges —
132	// is handed to the encoding/json walk, which reports the established format
133	// error (and any duplicate preceding the malformation) with the existing
134	// wording.
135	func checkDuplicateMembers(data []byte) error {
136		dup, recognized := scanDuplicateMembers(data)
137		// json.Valid confirms the whole document — including the numbers the
138		// walk skipped loosely and any trailing content — is one well-formed
139		// JSON value, so a completed walk's verdict can be trusted directly.
140		// Legal numbers beyond float64 range (e.g. 1e400) are valid JSON and
141		// pass; whether a number is acceptable for a given field is decided
142		// later by business validation.
143		if recognized && json.Valid(data) {
144			return dup
145		}
146		return checkJSONFormatAndDuplicates(data)
147	}
148	
149	// scanDuplicateMembers runs the duplicate-member policy over the shared
150	// structural walk. It reports the first duplicate in file order — the walk
151	// is depth-first in document order, so the second occurrence that appears
152	// earliest wins — and whether the walk recognized the document's structure
153	// (no errUndecided and no text problem, both of which leave the verdict to
154	// the decoder walk). recognized does not by itself mean the document is
155	// well-formed JSON: the caller confirms that with json.Valid.
156	func scanDuplicateMembers(data []byte) (dup error, recognized bool) {
157		// Each object's location in the document is unique, so the seen-name
158		// sets are keyed by the owning object's path; the walk needs no
159		// enter/exit events for them.
160		seen := make(map[string]map[string]struct{})
161		w := &jsonWalker{data: data, onMember: func(ownerPath, name string) error {
162			set := seen[ownerPath]
163			if set == nil {
164				set = make(map[string]struct{})
165				seen[ownerPath] = set
166			}
167			if _, ok := set[name]; ok {
168				dup = &duplicateMemberError{field: name, path: ownerPath}
169				return dup
170			}
171			set[name] = struct{}{}
172			return nil
173		}}
174		if err := w.value("$"); err != nil && dup == nil {
175			return nil, false
176		}
177		return dup, true
178	}
179	
180	// checkJSONFormatAndDuplicates is the encoding/json walk that documents the
181	// raw structural walk cannot recognize are handed to. It reports the JSON
182	// format error with the established wording — and a duplicate member when
183	// its second occurrence precedes the malformation — exactly as the duplicate
184	// check always has for such documents.
185	func checkJSONFormatAndDuplicates(data []byte) error {
186		dec := json.NewDecoder(bytes.NewReader(data))
187		// Numbers are only walked past, never interpreted: UseNumber keeps legal
188		// JSON numbers beyond float64 range (e.g. 1e400) from being turned into an
189		// unmarshal-overflow error here. Whether a number is acceptable for a given
190		// field is decided later by business validation.
191		dec.UseNumber()
192		if err := walkJSONValue(dec, "$"); err != nil {
193			return err
194		}
195		if _, err := dec.Token(); err != io.EOF {
196			if err == nil {
197				return errors.New("JSON 格式错误: 文档包含多余内容")
198			}
199			return fmt.Errorf("JSON 格式错误: %w", err)
200		}
201		return nil
202	}
203	
204	// walkJSONValue reads one complete JSON value whose first token has not been
205	// consumed yet. Together with walkJSONObject and walkJSONArray it is the
206	// decoding half of checkJSONFormatAndDuplicates: it only runs for documents
207	// the shared structural walk could not recognize, to report the format error
208	// (or an earlier duplicate) with the established wording.
209	func walkJSONValue(dec *json.Decoder, path string) error {
210		tok, err := dec.Token()
211		if err != nil {
212			if err == io.EOF {
213				return errors.New("JSON 格式错误: 文档为空")
214			}
215			return fmt.Errorf("JSON 格式错误: %w", err)
216		}
217		return walkJSONValueToken(dec, path, tok)
218	}
219	
220	// walkJSONValueToken reads the remainder of a value given its first token.
221	func walkJSONValueToken(dec *json.Decoder, path string, tok json.Token) error {
222		if d, ok := tok.(json.Delim); ok {
223			switch d {
224			case '{':
225				return walkJSONObject(dec, path)
226			case '[':
227				return walkJSONArray(dec, path)
228			default:
229				return fmt.Errorf("JSON 格式错误: 意外的分隔符 %q", d)
230			}
231		}
232		return nil // scalar value (string, number, bool, null)
233	}
234	
235	func walkJSONObject(dec *json.Decoder, path string) error {
236		seen := make(map[string]struct{})
237		for {
238			tok, err := dec.Token()
239			if err != nil {
240				if err == io.EOF {
241					return errors.New("JSON 格式错误: 对象未闭合")
242				}
243				return fmt.Errorf("JSON 格式错误: %w", err)
244			}
245			if d, ok := tok.(json.Delim); ok {
246				if d == '}' {
247					return nil
248				}
249				return fmt.Errorf("JSON 格式错误: 意外的分隔符 %q", d)
250			}
251			key, ok := tok.(string)
252			if !ok {
253				return errors.New("JSON 格式错误: 对象成员名必须是字符串")
254			}
255			if _, dup := seen[key]; dup {
256				return &duplicateMemberError{field: key, path: path}
257			}
258			seen[key] = struct{}{}
259			vtok, err := dec.Token()
260			if err != nil {
261				if err == io.EOF {
262					return errors.New("JSON 格式错误: 缺少成员值")
263				}
264				return fmt.Errorf("JSON 格式错误: %w", err)
265			}
266			if err := walkJSONValueToken(dec, joinMemberPath(path, key), vtok); err != nil {
267				return err
268			}
269		}
270	}
271	
272	func walkJSONArray(dec *json.Decoder, path string) error {
273		for i := 0; ; i++ {
274			tok, err := dec.Token()
275			if err != nil {
276				if err == io.EOF {
277					return errors.New("JSON 格式错误: 数组未闭合")
278				}
279				return fmt.Errorf("JSON 格式错误: %w", err)
280			}
281			if d, ok := tok.(json.Delim); ok && d == ']' {
282				return nil
283			}
284			if err := walkJSONValueToken(dec, joinIndexPath(path, i), tok); err != nil {
285				return err
286			}
287		}
288	}
289	
290	func buildReleaseInput(doc map[string]any) (ReleasePlanInput, error) {
291		app, err := requiredString(doc, "app")
292		if err != nil {
293			return ReleasePlanInput{}, err
294		}
295		revision, err := requiredString(doc, "revision")
296		if err != nil {
297			return ReleasePlanInput{}, err
298		}
299		image, err := requiredString(doc, "image")
300		if err != nil {
301			return ReleasePlanInput{}, err
302		}
303		batchSize, err := positiveInt(doc, "batchSize")
304		if err != nil {
305			return ReleasePlanInput{}, err
306		}
307		spreadBy, err := optionalSpreadBy(doc)
308		if err != nil {
309			return ReleasePlanInput{}, err
310		}
311		clusters, err := parseClusters(doc["clusters"])
312		if err != nil {
313			return ReleasePlanInput{}, err
314		}
315		include, err := parseConditions(doc, "include")
316		if err != nil {
317			return ReleasePlanInput{}, err
318		}
319		exclude, err := parseConditions(doc, "exclude")
320		if err != nil {
321			return ReleasePlanInput{}, err
322		}
323	
324		return ReleasePlanInput{
325			App:       app,
326			Revision:  revision,
327			Image:     image,
328			BatchSize: batchSize,
329			Clusters:  clusters,
330			Include:   include,
331			Exclude:   exclude,
332			SpreadBy:  spreadBy,
333		}, nil
334	}
335	
336	// optionalSpreadBy reads the optional "spreadBy" field: absent or an empty
337	// string disables fault-domain spreading; a non-string value or a string of
338	// only whitespace is rejected. The tag key is used exactly as written.
339	func optionalSpreadBy(doc map[string]any) (string, error) {
340		v, ok := doc["spreadBy"]
341		if !ok {
342			return "", nil
343		}
344		s, ok := v.(string)
345		if !ok {
346			return "", fmt.Errorf("字段 %q 必须是字符串", "spreadBy")
347		}
348		if err := checkSpreadBy(s); err != nil {
349			return "", err
350		}
351		return s, nil
352	}
353	
354	// checkSpreadBy rejects a spreadBy value that is neither empty nor a usable
355	// tag key: a string of only whitespace can never match a valid tag key.
356	func checkSpreadBy(s string) error {
357		if s != "" && strings.TrimSpace(s) == "" {
358			return fmt.Errorf("字段 %q 不能只含空白", "spreadBy")
359		}
360		return nil
361	}
362	
363	// ValidateReleaseInput checks that a release configuration is well-formed.
364	// Every string is first required to be legal UTF-8 — app, revision, image,
365	// spreadBy, every candidate's ID and tag keys/values (disabled and
366	// filtered-out candidates included), and every include/exclude condition's
367	// keys and values — because invalid bytes would later be rewritten to "�"
368	// while the plan is written as JSON and could merge two distinct identities
369	// or take part in label matching as an ordinary value. That text check runs
370	// before any business rule, in a fixed order (field order, then candidate
371	// and condition positions from zero, then keys in ascending order), so the
372	// one problem it reports never depends on map iteration. Business
373	// validation then runs as before: app/revision/image are non-empty,
374	// batchSize is a positive integer, spreadBy is empty or a usable tag key
375	// (not whitespace-only), cluster IDs are unique across every candidate
376	// (including disabled and filtered-out clusters), and tag/condition keys
377	// are non-empty. Errors name the field and the position in its list; within
378	// a cluster the ID is checked before its tags, and tag keys are examined in
379	// ascending order so repeated calls report the same error. The input is
380	// never mutated. MakeReleasePlan calls this automatically; library callers
381	// may use it to validate without planning.
382	func ValidateReleaseInput(in ReleasePlanInput) error {
383		if err := validateStrictText(in); err != nil {
384			return err
385		}
386		if strings.TrimSpace(in.App) == "" {
387			return errors.New(`字段 "app" 不能为空或只含空白`)
388		}
389		if strings.TrimSpace(in.Revision) == "" {
390			return errors.New(`字段 "revision" 不能为空或只含空白`)
391		}
392		if strings.TrimSpace(in.Image) == "" {
393			return errors.New(`字段 "image" 不能为空或只含空白`)
394		}
395		if in.BatchSize <= 0 {
396			return errors.New(`字段 "batchSize" 必须是正整数`)
397		}
398		if err := checkSpreadBy(in.SpreadBy); err != nil {
399			return err
400		}
401		ids := newClusterIDSet(len(in.Clusters))
402		for i, c := range in.Clusters {
403			if err := ids.check(i, c.ID); err != nil {
404				return err
405			}
406			if err := validateTagKeys(i, c.Tags); err != nil {
407				return err
408			}
409		}
410		if err := validateConditionKeys("include", in.Include); err != nil {
411			return err
412		}
413		if err := validateConditionKeys("exclude", in.Exclude); err != nil {
414			return err
415		}
416		return nil
417	}
418	
419	// validateTagKeys applies the shared label-key rule to one cluster's tags,
420	// reporting the cluster's position in the candidate list.
421	func validateTagKeys(clusterIndex int, tags map[string]string) error {
422		if hasEmptyLabelKey(tags) {
423			return fmt.Errorf("clusters[%d] 的标签键不能为空", clusterIndex)
424		}
425		return nil
426	}
427	
428	// validateConditionKeys applies the shared condition rules to every condition
429	// in original order, so the first invalid condition is reported.
430	func validateConditionKeys(field string, conds []LabelCondition) error {
431		for i, cond := range conds {
432			if err := validateCondition(field, i, cond); err != nil {
433				return err
434			}
435		}
436		return nil
437	}
438	
439	func requiredString(doc map[string]any, field string) (string, error) {
440		v, ok := doc[field]
441		if !ok {
442			return "", fmt.Errorf("缺少必需字段 %q", field)
443		}
444		s, ok := v.(string)
445		if !ok {
446			return "", fmt.Errorf("字段 %q 必须是字符串", field)
447		}
448		if strings.TrimSpace(s) == "" {
449			return "", fmt.Errorf("字段 %q 不能为空或只含空白", field)
450		}
451		return s, nil
452	}
453	
454	func positiveInt(doc map[string]any, field string) (int, error) {
455		v, ok := doc[field]
456		if !ok {
457			return 0, fmt.Errorf("缺少必需字段 %q", field)
458		}
459		n, ok := v.(json.Number)
460		if !ok {
461			return 0, fmt.Errorf("字段 %q 必须是正整数", field)
462		}
463		i, err := n.Int64()
464		if err != nil || i <= 0 {
465			return 0, fmt.Errorf("字段 %q 必须是正整数", field)
466		}
467		return int(i), nil
468	}
469	
470	func parseClusters(v any) ([]Cluster, error) {
471		if v == nil {
472			return nil, errors.New("缺少必需字段 \"clusters\"")
473		}
474		raw, ok := v.([]any)
475		if !ok {
476			return nil, errors.New("字段 \"clusters\" 必须是数组")
477		}
478		clusters := make([]Cluster, 0, len(raw))
479		ids := newClusterIDSet(len(raw))
480		for i, item := range raw {
481			obj, ok := item.(map[string]any)
482			if !ok {
483				return nil, fmt.Errorf("clusters[%d] 必须是对象", i)
484			}
485			id, err := clusterIDFromJSON(obj, i, ids)
486			if err != nil {
487				return nil, err
488			}
489	
490			disabled := false
491			if dv, present := obj["disabled"]; present {
492				b, ok := dv.(bool)
493				if !ok {
494					return nil, fmt.Errorf("集群 %q 的 \"disabled\" 必须是布尔值", id)
495				}
496				disabled = b
497			}
498	
499			tags := map[string]string{}
500			if tv, present := obj["tags"]; present {
501				tm, ok := tv.(map[string]any)
502				if !ok {
503					return nil, fmt.Errorf("集群 %q 的 \"tags\" 必须是对象", id)
504				}
505				tags, err = labelsFromJSON(tm,
506					func(string) error { return fmt.Errorf("集群 %q 的标签键不能为空", id) },
507					func(k string) error { return fmt.Errorf("集群 %q 的标签 %q 值必须是字符串", id, k) },
508				)
509				if err != nil {
510					return nil, err
511				}
512			}
513	
514			clusters = append(clusters, Cluster{ID: id, Disabled: disabled, Tags: tags})
515		}
516		return clusters, nil
517	}
518	
519	// clusterIDFromJSON reads the "id" member of one candidate object and applies
520	// the shared cluster-identity rule. A missing member or a non-string value is
521	// a JSON decoding problem with its own reason; an empty or duplicate ID is
522	// reported by the shared rule exactly as for a directly constructed config.
523	func clusterIDFromJSON(obj map[string]any, index int, ids *clusterIDSet) (string, error) {
524		v, ok := obj["id"]
525		if !ok {
526			return "", fmt.Errorf("clusters[%d]: 缺少必需字段 %q", index, "id")
527		}
528		id, ok := v.(string)
529		if !ok {
530			return "", fmt.Errorf("clusters[%d]: 字段 %q 必须是字符串", index, "id")
531		}
532		if err := ids.check(index, id); err != nil {
533			return "", err
534		}
535		return id, nil
536	}
537	
538	// parseConditions reads the optional include/exclude field from the decoded
539	// document. An absent field means "no conditions" (the same as an explicit
540	// empty array); a field that is present must be an array of condition
541	// objects. An explicit JSON null is a field type error — it must not be read
542	// as "no conditions", which would silently drop the filter the author wrote.
543	func parseConditions(doc map[string]any, field string) ([]LabelCondition, error) {
544		v, ok := doc[field]
545		if !ok {
546			return []LabelCondition{}, nil
547		}
548		raw, ok := v.([]any)
549		if !ok {
550			return nil, fmt.Errorf("字段 %q 必须是条件数组", field)
551		}
552		conds := make([]LabelCondition, 0, len(raw))
553		for i, item := range raw {
554			obj, ok := item.(map[string]any)
555			if !ok {
556				return nil, fmt.Errorf("%s[%d] 必须是对象", field, i)
557			}
558			cond, err := labelsFromJSON(obj,
559				func(string) error { return fmt.Errorf("%s[%d] 的标签键不能为空", field, i) },
560				func(k string) error { return fmt.Errorf("%s[%d] 的标签 %q 值必须是字符串", field, i, k) },
561			)
562			if err != nil {
563				return nil, err
564			}
565			if err := validateCondition(field, i, cond); err != nil {
566				return nil, err
567			}
568			conds = append(conds, cond)
569		}
570		return conds, nil
571	}
572	
573	// MakeReleasePlan selects available clusters, orders them by ID, and splits
574	// them into batches. When SpreadBy names a tag, each batch holds at most one
575	// cluster per value of that tag (its fault domain) and every selected cluster
576	// must carry the tag. It validates the input first and never mutates it.
577	func MakeReleasePlan(in ReleasePlanInput) (ReleasePlan, error) {
578		if err := ValidateReleaseInput(in); err != nil {
579			return ReleasePlan{}, err
580		}
581		if len(in.Clusters) == 0 {
582			return ReleasePlan{}, errors.New("没有可发布的集群：未提供候选集群")
583		}
584	
585		selected := []string{}
586		excluded := []ExcludedCluster{}
587		for _, c := range in.Clusters {
588			switch {
589			case c.Disabled:
590				excluded = append(excluded, ExcludedCluster{ID: c.ID, Reason: ReasonDisabled})
591			case matchesAny(c.Tags, in.Exclude):
592				excluded = append(excluded, ExcludedCluster{ID: c.ID, Reason: ReasonExcludeMatched})
593			case len(in.Include) > 0 && !matchesAny(c.Tags, in.Include):
594				excluded = append(excluded, ExcludedCluster{ID: c.ID, Reason: ReasonIncludeNotMatched})
595			default:
596				selected = append(selected, c.ID)
597			}
598		}
599	
600		sort.Strings(selected)
601		sort.Slice(excluded, func(i, j int) bool { return excluded[i].ID < excluded[j].ID })
602	
603		if len(selected) == 0 {
604			var b strings.Builder
605			b.WriteString("没有符合规则的可用集群，各候选集群未入选原因：")
606			for _, e := range excluded {
607				b.WriteString("\n  ")
608				b.WriteString(e.ID)
609				b.WriteString("：")
610				b.WriteString(e.Reason)
611			}
612			return ReleasePlan{}, errors.New(b.String())
613		}
614	
615		var batches []Batch
616		if in.SpreadBy == "" {
617			batches = chunkBatches(selected, in.BatchSize)
618		} else {
619			domains, err := faultDomains(in.Clusters, selected, in.SpreadBy)
620			if err != nil {
621				return ReleasePlan{}, err
622			}
623			batches = spreadBatches(selected, domains, in.BatchSize)
624		}
625	
626		return ReleasePlan{
627			App:      AppInfo{Name: in.App, Revision: in.Revision, Image: in.Image},
628			Batches:  batches,
629			Excluded: excluded,
630		}, nil
631	}
632	
633	// chunkBatches splits the ascending IDs into batches of at most batchSize.
634	func chunkBatches(selected []string, batchSize int) []Batch {
635		batches := []Batch{}
636		for i := 0; i < len(selected); i += batchSize {
637			end := i + batchSize
638			if end > len(selected) {
639				end = len(selected)
640			}
641			batches = append(batches, Batch{Index: len(batches) + 1, Clusters: selected[i:end]})
642		}
643		return batches
644	}
645	
646	// faultDomains maps every selected cluster ID to the exact value of its
647	// spreadBy tag. A selected cluster missing the tag fails the whole plan;
648	// selected is ascending, so the smallest such ID is reported. An empty
649	// string tag value is a valid fault domain, distinct from a missing tag.
650	func faultDomains(clusters []Cluster, selected []string, spreadBy string) (map[string]string, error) {
651		tagsByID := make(map[string]map[string]string, len(clusters))
652		for _, c := range clusters {
653			tagsByID[c.ID] = c.Tags
654		}
655		domains := make(map[string]string, len(selected))
656		for _, id := range selected {
657			v, ok := tagsByID[id][spreadBy]
658			if !ok {
659				return nil, fmt.Errorf("集群 %q 缺少故障域标签 %q", id, spreadBy)
660			}
661			domains[id] = v
662		}
663		return domains, nil
664	}
665	
666	// spreadBatches packs the ascending IDs into batches of at most batchSize
667	// with at most one cluster per fault domain in each batch. Each batch takes
668	// the smallest still-unscheduled IDs whose domains do not conflict with the
669	// batch; conflicting clusters are deferred to later batches, so a batch may
670	// be short only when no non-conflicting cluster remains. Every ID appears in
671	// exactly one batch and IDs stay ascending within a batch.
672	func spreadBatches(selected []string, domains map[string]string, batchSize int) []Batch {
673		remaining := append([]string(nil), selected...)
674		batches := []Batch{}
675		for len(remaining) > 0 {
676			// The map never holds more entries than there are remaining clusters,
677			// so size it by them — never by batchSize, which is only an upper
678			// bound and may be a huge legal value (e.g. 1e9 meaning "no limit").
679			used := make(map[string]struct{}, min(batchSize, len(remaining)))
680			batch := []string{}
681			deferred := []string{}
682			for _, id := range remaining {
683				d := domains[id]
684				if _, conflict := used[d]; len(batch) < batchSize && !conflict {
685					used[d] = struct{}{}
686					batch = append(batch, id)
687				} else {
688					deferred = append(deferred, id)
689				}
690			}
691			batches = append(batches, Batch{Index: len(batches) + 1, Clusters: batch})
692			remaining = deferred
693		}
694		return batches
695	}
696	
697	func matchesAny(tags map[string]string, conditions []LabelCondition) bool {
698		for _, cond := range conditions {
699			if matchesAll(tags, cond) {
700				return true
701			}
702		}
703		return false
704	}
705	
706	func matchesAll(tags map[string]string, cond LabelCondition) bool {
707		for k, v := range cond {
708			tv, ok := tags[k]
709			if !ok || tv != v {
710				return false
711			}
712		}
713		return true
714	}
715

